package com.example.myapplication

import android.content.res.AssetManager
import fi.iki.elonen.NanoHTTPD
import java.io.IOException
import java.io.InputStream

/**
 * A minimal NanoHTTPD-based server that serves files from the app's assets/www/ folder.
 * Requests to "/" will serve "assets/www/index.html". Other paths map to assets/www/<path>.
 */
class LocalWebServer(private val assets: AssetManager, port: Int = 8080) : NanoHTTPD(port) {
    override fun serve(session: IHTTPSession): Response {
        var uri = session.uri.trimStart('/')
        if (uri.isEmpty() || uri.endsWith("/")) {
            uri = uri + "index.html"
        }
        val assetPath = "www/$uri"

        return try {
            val input: InputStream = assets.open(assetPath)
            val mime = mimeTypeForPath(assetPath)
            // Use chunked response so we don't rely on InputStream.available()
            newChunkedResponse(Response.Status.OK, mime, input)
        } catch (_: IOException) {
            newFixedLengthResponse(Response.Status.NOT_FOUND, "text/plain", "Not found")
        }
    }

    private fun mimeTypeForPath(path: String): String {
        return when {
            path.endsWith(".html") || path.endsWith(".htm") -> "text/html"
            path.endsWith(".js") -> "application/javascript"
            path.endsWith(".css") -> "text/css"
            path.endsWith(".png") -> "image/png"
            path.endsWith(".jpg") || path.endsWith(".jpeg") -> "image/jpeg"
            path.endsWith(".svg") -> "image/svg+xml"
            path.endsWith(".json") -> "application/json"
            else -> "application/octet-stream"
        }
    }
}

package com.example.myapplication

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.tooling.preview.Preview
import com.example.myapplication.ui.theme.MyApplicationTheme

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            MyApplicationTheme {
                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
                    Greeting(
                        name = "Android",
                        modifier = Modifier.padding(innerPadding)
                    )
                }
            }
        }
    }
}

@Composable
fun Greeting(name: String, modifier: Modifier = Modifier) {
    Text(
        text = "Hello $name!",
        modifier = modifier
    )
}

@Preview(showBackground = true)
@Composable
fun GreetingPreview() {
    MyApplicationTheme {
        Greeting("Android")
    }
}

package com.example.myapplication

import android.os.Bundle
import android.util.Log
import android.view.View
import android.webkit.WebResourceRequest
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.core.view.WindowCompat
import androidx.core.view.WindowInsetsControllerCompat
import androidx.core.view.WindowInsetsCompat
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.viewinterop.AndroidView
import com.example.myapplication.ui.theme.MyApplicationTheme

class MainActivity : ComponentActivity() {
    private var server: LocalWebServer? = null
    private var serverStarted = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        // Hide the system bars (status bar + navigation bar) for an immersive experience
        WindowCompat.setDecorFitsSystemWindows(window, false)
        val controller = WindowInsetsControllerCompat(window, window.decorView)
        // Allow system bars to be revealed transiently via swipe
        controller.systemBarsBehavior = WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE
        // Hide both status and navigation bars
        controller.hide(WindowInsetsCompat.Type.statusBars())
        controller.hide(WindowInsetsCompat.Type.navigationBars())

        // Start the embedded HTTP server that serves files from assets/www
        try {
            server = LocalWebServer(assets, 8080)
            server?.start()
            serverStarted = true
            Log.i("MainActivity", "LocalWebServer started on port 8080")
        } catch (e: Exception) {
            serverStarted = false
            Log.e("MainActivity", "Failed to start LocalWebServer", e)
        }

        setContent {
            MyApplicationTheme {
                // Use a WebView to load the local server root (fallback to assets file if server unavailable)
                WebContent(serverStarted)
            }
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        // Stop server when activity is destroyed
        server?.stop()
    }
}

@Composable
fun WebContent(serverAvailable: Boolean, modifier: Modifier = Modifier) {
    AndroidView(factory = { ctx ->
        WebView(ctx).apply {
            settings.javaScriptEnabled = true
            settings.domStorageEnabled = true
            settings.useWideViewPort = true
            settings.loadWithOverviewMode = true
            settings.builtInZoomControls = false
            settings.displayZoomControls = false
            settings.textZoom = 100
            settings.mediaPlaybackRequiresUserGesture = false
            // Enable WebView debugging so you can inspect via chrome://inspect
            WebView.setWebContentsDebuggingEnabled(true)
            // Prefer hardware layer for better canvas/GL rendering
            setLayerType(View.LAYER_TYPE_HARDWARE, null)
            overScrollMode = View.OVER_SCROLL_NEVER
            isVerticalScrollBarEnabled = false
            isHorizontalScrollBarEnabled = false

            webViewClient = object : WebViewClient() {
                override fun onReceivedError(view: WebView?, request: WebResourceRequest?, error: android.webkit.WebResourceError?) {
                    // On error, fall back to loading the local asset file so user isn't left with blank white screen
                    try {
                        loadUrl("file:///android_asset/www/index.html")
                    } catch (_: Exception) { }
                }

                override fun onPageFinished(view: WebView?, url: String?) {
                    super.onPageFinished(view, url)
                    try {
                        // Give the page a moment to finish its own layout, then force the Scratch host/root to fill the viewport.
                        view?.postDelayed({
                            val js = """
                                (function() {
                                  var styleId = '__webview_scratch_fix__';
                                  if (!document.getElementById(styleId)) {
                                    var style = document.createElement('style');
                                    style.id = styleId;
                                    style.textContent = [
                                      'html, body, #app { width: 100%; height: 100%; margin: 0; padding: 0; overflow: hidden; }',
                                      '.sc-root { width: 100vw !important; height: 100vh !important; max-width: none !important; max-height: none !important; }',
                                      '.sc-layers, .sc-scaled-overlays-outer, .sc-scaled-overlays-inner { width: 100%; height: 100%; }',
                                      'canvas { display: block; }',
                                      'canvas.sc-canvas { width: 100% !important; height: 100% !important; }'
                                    ].join('\n');
                                    (document.head || document.documentElement).appendChild(style);
                                  }

                                  var root = document.querySelector('.sc-root');
                                  if (root) {
                                    root.style.width = '100vw';
                                    root.style.height = '100vh';
                                  }

                                  var stage = document.querySelector('canvas.sc-canvas') || document.querySelector('.sc-root canvas');
                                  if (stage) {
                                    stage.style.width = '100%';
                                    stage.style.height = '100%';
                                    stage.style.display = 'block';
                                    stage.style.touchAction = 'none';
                                  }

                                  var rootRect = root ? root.getBoundingClientRect() : null;
                                  var stageRect = stage ? stage.getBoundingClientRect() : null;
                                  return 'ROOT|' + (rootRect ? [rootRect.width, rootRect.height, rootRect.left, rootRect.top].join('|') : 'NO_ROOT') +
                                         '|CANVAS|' + (stageRect ? [stageRect.width, stageRect.height, stageRect.left, stageRect.top].join('|') : 'NO_STAGE');
                                })();
                            """.trimIndent()

                            evaluateJavascript(js) { result ->
                            // result is a quoted string from JS
                            Log.i("WebContentDebug", "onPageFinished eval result: $result")
                            }
                        }, 250)
                    } catch (e: Exception) {
                        Log.e("WebContentDebug", "evaluateJavascript failed", e)
                    }
                }
            }

            if (serverAvailable) {
                loadUrl("http://127.0.0.1:8080/")
            } else {
                // fallback to file asset if server couldn't start
                loadUrl("file:///android_asset/www/index.html")
            }
        }
    }, modifier = modifier.fillMaxSize())
}
